package com.example.ecommerce.servlet;
import com.example.ecommerce.dao.OrderDAO; import javax.servlet.*; import javax.servlet.annotation.*; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/admin/orders") public class AdminOrderServlet extends HttpServlet{OrderDAO dao=new OrderDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{String id=req.getParameter("id");if(id!=null){req.setAttribute("order",dao.findById(Integer.parseInt(id)));req.getRequestDispatcher("/WEB-INF/views/admin/order-detail.jsp").forward(req,resp);return;}req.setAttribute("orders",dao.findAll());req.getRequestDispatcher("/WEB-INF/views/admin/orders.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{dao.updateStatus(Integer.parseInt(req.getParameter("id")),req.getParameter("status"));resp.sendRedirect(req.getContextPath()+"/admin/orders");}catch(Exception e){throw new ServletException(e);}}}
